<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){exit("Somente CLI.\n");}$root=dirname(__DIR__);require_once $root.'/config/nexa_env.php';require $root.'/config/pdo.php';require_once $root.'/config/fiscal_module.php';fiscal_ensure_aux_schema($pdo);$company=1;
try{$pdo->beginTransaction();$pdo->prepare("INSERT INTO fiscal_ibs_cbs_classifications (company_id,classification_code,description,cst_code,can_nfe,can_nfce,is_active,updated_at) VALUES (?,'000001','LOCAL BLOQUEADO','999',0,0,1,NOW()) ON DUPLICATE KEY UPDATE description='LOCAL BLOQUEADO',cst_code='999',can_nfe=0,can_nfce=0,is_active=1,updated_at=NOW()")->execute([$company]);$r=fiscal_ibs_cbs_classification_direct($pdo,$company,'000001','2026-07-26');if(!$r||(int)$r['company_id']!==0||($r['cst_code']??'')!=='000')throw new RuntimeException('A classificação local ainda substitui o catálogo global.');$pdo->prepare("INSERT INTO fiscal_cbs_rates (company_id,code,validity_start,validity_end,rate,is_active) VALUES (?,'TESTE_LOCAL','2026-01-01','2026-12-31',99,1) ON DUPLICATE KEY UPDATE rate=99,is_active=1")->execute([$company]);$rate=fiscal_current_cbs_rate($pdo,$company,'2026-07-26');if(!$rate||(int)$rate['company_id']!==0||(float)$rate['rate']>=99)throw new RuntimeException('A alíquota CBS local ainda substitui a global.');$pdo->rollBack();echo "[OK] Classificação IBS/CBS global não é substituída por empresa.\n[OK] Alíquotas globais não são substituídas por empresa.\n[OK] Isolamento v2.6 validado.\n";}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,'[ERRO] '.$e->getMessage()."\n");exit(1);}
